
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('sv-SE'), money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:2});
const orderLabel=value=>Number.isSafeInteger(Number(value))&&Number(value)>0?String(value).padStart(3,'0'):'Aguardando sincronização';
const key='l2one_state_v2', defaults={sectors:[],team:[],sellers:[],industries:[],priceTables:[],whatsappTemplates:[],clients:[],leads:[],opportunities:[],interactions:[],fulfillments:[],settlements:[],visits:[],orders:[],tasks:[],goals:[],routes:[],prices:[],commissionRates:[],commissionReceipts:[],officeProcesses:[],officeActions:[],officeCommercial:[],officeAdministrative:[],officeRituals:[],officeRoles:[],officeFinance:[],officeBudget:[],officeMonthlyClose:[],cashDays:[],cashEntries:[],user:'Ana Paula',server:'',token:'',mustChangePassword:false,syncAt:'',pending:[]};
