for(const name of ['sellerCommissions','sellers','commissionRates','commissionReceipts','whatsappTemplates','leads','opportunities','interactions','fulfillments','settlements','industries','priceTables','sectors','team'])if(!Array.isArray(s[name]))s[name]=[];
