function queue(type,data){data.updatedAt=new Date().toISOString();data.updatedBy=s.user;if(type==='order'){data.quotedAt=data.quotedAt||s.orders.find(o=>o.id===data.id)?.quotedAt;if(data.status==='Orçamento'){data.quotedAt=data.quotedAt||new Date().toISOString();const saved=s.orders.find(o=>o.id===data.id);if(saved)saved.quotedAt=data.quotedAt}}s.pending.push({type,data:structuredClone(data),changeId:uid()});save();window.L2Live?.saved()}
function digits(value){return String(value||'').replace(/\D/g,'')}
function validCNPJ(value){
 const n=digits(value);
 if(n.length!==14||/^(\d)\1{13}$/.test(n))return false;
 const check=len=>{let sum=0,weight=len-7;for(let i=0;i<len;i++){sum+=Number(n[i])*weight;weight=weight===2?9:weight-1}let mod=sum%11;return mod<2?0:11-mod};
 return Number(n[12])===check(12)&&Number(n[13])===check(13);
}
function newClient(){show('clientes');$('clientEditor').open=true;$('c_taxId').required=true;$('c_stateRegistration').required=true;$('clientForm').reset();$('cid').value='';$('clientFormTitle').textContent='Cadastrar novo cliente';$('clientEditor').scrollIntoView({behavior:'smooth',block:'start'});$('c_name').focus()}
function saveClient(e){
 e.preventDefault();
 const d=Object.fromEntries(new FormData(e.target));
 d.name=d.name.trim();d.city=d.city.trim();d.state=stateCode(d);if(!d.owner&&!sectionAllowed('admin'))d.owner=s.user;
 if(!d.name||!d.city||!['PA','AP'].includes(d.state)){alert('Informe razão social, cidade e UF válida (PA ou AP).');return}
 const legacy=s.clients.find(c=>c.id===d.id&&!c.taxId&&!c.stateRegistration);if(!legacy&&!validCNPJ(d.taxId)){alert('Informe um CNPJ válido, com 14 dígitos e dígitos verificadores corretos.');$('c_taxId').focus();return}
 d.taxId=digits(d.taxId);
 d.stateRegistration=(d.stateRegistration||'').trim().toUpperCase();
 if(!legacy&&d.stateRegistration!=='ISENTO'&&!/^\d{7,14}$/.test(d.stateRegistration)){alert('Informe a inscrição estadual (7 a 14 dígitos) ou ISENTO.');$('c_stateRegistration').focus();return}
 if(d.stateRegistration!=='ISENTO')d.stateRegistration=digits(d.stateRegistration);
 if(d.potential){const potentialCents=parseBRLCents(d.potential);if(!Number.isSafeInteger(potentialCents)||potentialCents<0){alert('Potencial estimado inválido.');return}d.potential=(potentialCents/100).toFixed(2)}
  const old=s.clients.findIndex(c=>c.id===d.id);
 if(d.taxId&&s.clients.some(c=>c.id!==d.id&&digits(c.taxId)===d.taxId)){alert('Já existe um cliente com este CNPJ. Confira o cadastro antes de salvar.');return}
 d.id=d.id||uid();
 const merged=old<0?d:{...s.clients[old],...d};
 if(old<0)s.clients.push(merged);else s.clients[old]=merged;
 queue('client',merged);const lead=s.leads.find(x=>x.taxId===d.taxId);if(lead){lead.clientId=d.id;lead.status='Convertido';lead.convertedAt=new Date().toISOString();queue('lead',lead)}show('clientes');
}
