 for(let k of ['name','tradeName','taxId','stateRegistration','contact','phone','email','address','district','city','state','channel','origin','owner','classification','potential','visitDay','brands','last_purchase'])$('c_'+k).value=c[k]||'';
 if(c.owner&&!Array.from($('c_owner').options).some(option=>option.value===c.owner))$('c_owner').add(new Option(c.owner+' (cadastro existente)',c.owner));if(c.owner)$('c_owner').value=c.owner;
 $('c_potential').value=c.potential?formatBRLInput(c.potential):'';$('c_state').value=stateCode(c)==='FORA'?'':stateCode(c);$('c_taxId').required=!!c.taxId;$('c_stateRegistration').required=!!c.stateRegistration;
