function prefill(id){window.prefillId=id;show('registro')}
function priceCents(value){let n=Number(String(value??0).replace(',','.'));return Number.isFinite(n)?Math.round(n*100):0}
function parseBRLCents(value){let t=String(value??'').trim().replace(/^R\$\s*/i,'').replace(/\s/g,'');if(!t)return NaN;let whole,decimal='';if(t.includes(',')){let parts=t.split(',');if(parts.length!==2||!/^\d{1,3}(?:\.\d{3})*$|^\d+$/.test(parts[0])||!/^\d{1,2}$/.test(parts[1]))return NaN;whole=parts[0].replace(/\./g,'');decimal=parts[1]}else if(/^\d{1,3}(?:\.\d{3})+$/.test(t)){whole=t.replace(/\./g,'')}else if(/^\d+(?:\.\d{1,2})?$/.test(t)){let parts=t.split('.');whole=parts[0];decimal=parts[1]||''}else return NaN;let cents=Number(whole)*100+Number(decimal.padEnd(2,'0'));return Number.isSafeInteger(cents)?cents:NaN}
function formatBRLInput(value){let n=Number(value);return Number.isFinite(n)?n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}):''}
function catalogTableId(p){return p.tableId||p.brand+'|'+p.state}
function catalogPriceId(p){return p.id||catalogTableId(p)+'|'+p.sku}
function eligibleTables(state){return s.priceTables.filter(t=>t.active&&(t.state===state||t.state==='ALL')&&s.industries.some(i=>i.name===t.brand&&i.active))}
function pricesForTable(priceTable){const selected=window.currentOrder?.tableSelections||{},tables=eligibleTables(priceTable);return (s.prices||[]).filter(p=>{const choices=tables.filter(t=>t.brand===p.brand),id=selected[p.brand]||(choices.length===1?choices[0].id:'');return catalogTableId(p)===id})}
function orderCommercialTablesHTML(draft){const tables=eligibleTables(draft.priceTable),brands=[...new Set(tables.map(t=>t.brand))];return `<div class="box"><h3>Tabelas comerciais por indústria</h3><p>Escolha a tabela cadastrada. A UF define a abrangência; não limita a quantidade de tabelas.</p><div class="row">${brands.map(brand=>{const choices=tables.filter(t=>t.brand===brand),chosen=draft.tableSelections?.[brand]||(choices.length===1?choices[0].id:'');return `<label>${esc(brand)}<select aria-label="Tabela comercial ${esc(brand)}" onchange="setOrderCommercialTable('${esc(brand)}',this.value)"><option value="">Selecione a tabela</option>${choices.map(t=>`<option value="${esc(t.id)}" ${chosen===t.id?'selected':''}>${esc(t.title)}${t.audience?' · '+esc(t.audience):''}</option>`).join('')}</select></label>`}).join('')}</div>${tables.some(t=>t.brand==='Bella Brazil')?`<p> Bella Brazil: caixas de 6 por cor · CIF · mínimo PA R$ 2.000 / AP R$ 3.000 · entrega 6–9 dias após confirmação · pagamento 28, 28/35 ou 30/45/60${financeAllowed()?' · comissão '+tables.filter(t=>t.brand==='Bella Brazil').map(t=>t.channel+': '+t.commissionRate+'%').join(' · ')+' (dia 15, fechamento 1–30)':''}.</p><label>Bonificação Bella Brazil em produtos (%)<input name="bellaBonusPercent" type="number" min="0" max="100" step="0.01" value="${esc(draft.bellaBonusPercent||0)}" onchange="orderDraft().bellaBonusPercent=this.value"></label><label>Aprovação de bonificação após primeiro pedido<input name="bellaBonusApproval" value="${esc(draft.bellaBonusApproval||'')}" onchange="orderDraft().bellaBonusApproval=this.value" placeholder="Consulta prévia e aprovação da administradora"></label><p>Primeiro pedido: 5% a 15%, ou zero sem bonificação. Demais solicitações sob consulta prévia.</p>`:''}</div>`}
function preserveOrderFields(){const f=$('orderForm');if(f){const d=orderDraft();for(const k of ['paymentTerms','notes','status','sellerResponsible'])if(f.elements[k])d[k]=f.elements[k].value}}
function setOrderCommercialTable(brand,id){preserveOrderFields();const d=orderDraft();d.tableSelections={...(d.tableSelections||{}),[brand]:id};for(const key of Object.keys(d.quantities))if(key.startsWith(brand+'|'))delete d.quantities[key];CommercialDrafts.persistOrder();show('pedidos')}
function orderBrands(order){return [...new Set((order.items||[]).map(i=>i.brand||order.brand).filter(b=>b&&b!=='Multimarcas').concat(order.items?.length?[]:(order.brand&&order.brand!=='Multimarcas'?[order.brand]:[])))]}
function orderBrandTotals(order){const totals=new Map();for(const item of order.items||[]){const brand=item.brand||order.brand;if(!brand||brand==='Multimarcas')continue;const cents=Number.isFinite(Number(item.subtotal))?priceCents(item.subtotal):priceCents(item.unitPrice)*Number(item.quantity||0);totals.set(brand,(totals.get(brand)||0)+cents)}if(!totals.size&&order.brand&&order.brand!=='Multimarcas')totals.set(order.brand,priceCents(order.amount));return totals}
