async function manageOrderInvoices(id){const panel=$('orderInvoices');if(!panel||!s.token)return alert('Entre no sistema para confrontar NF-e.');panel.textContent='Consultando notas…';try{const order=s.orders.find(x=>x.id===id);if(!order)throw Error('Pedido não encontrado');const r=await fetch(s.server+'/api/orders/'+encodeURIComponent(id)+'/invoices',{headers:{Authorization:'Bearer '+s.token}});const rows=await r.json();if(!r.ok)throw Error(rows.detail||'Consulta recusada');const brands=[...new Set((order.items||[]).map(i=>i.brand||order.brand))];panel.innerHTML=`<div class="box"><h3>Confronto do pedido ${esc(orderLabel(order.orderNumber))}</h3><p class="muted">Anexe o XML da NF-e de cada indústria. O confronto é automático por SKU, quantidade e valor. PDF não contém dados estruturados suficientes; anexe-o em Comprovantes.</p><form onsubmit="uploadOrderInvoice(event)" data-order="${esc(id)}"><label>Indústria<select name="brand" required>${brands.map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join('')}</select></label><label>XML da NF-e<input name="file" type="file" accept=".xml,text/xml,application/xml" required></label><button>Enviar e confrontar</button></form><p id="invoiceNotice" role="status"></p>${rows.map(x=>`<div class="box"><b>NF-e ${esc(x.invoiceNumber)} · ${esc(x.brand)} · ${esc(x.status)}</b><p>Pedido: ${money(x.orderTotal)} · Faturado: ${money(x.invoiceTotal)}</p>${x.differences?.length?`<div class="scroll"><table><tr><th>SKU</th><th>Qtd. pedido</th><th>Qtd. nota</th><th>Valor pedido</th><th>Valor nota</th></tr>${x.differences.map(d=>`<tr><td>${esc(d.sku)}</td><td>${esc(d.pedidoQuantidade)}</td><td>${esc(d.notaQuantidade)}</td><td>${money(d.pedidoValor)}</td><td>${money(d.notaValor)}</td></tr>`).join('')}</table></div>`:'Sem divergências nos itens confrontados.'}</div>`).join('')}</div>`;panel.scrollIntoView({behavior:'smooth'})}catch(err){panel.textContent=err.message}}
async function uploadOrderInvoice(event){event.preventDefault();const form=event.target,id=form.dataset.order,data=new FormData(form),notice=$('invoiceNotice');notice.textContent='Processando NF-e…';try{const r=await fetch(s.server+'/api/orders/'+encodeURIComponent(id)+'/invoices',{method:'POST',headers:{Authorization:'Bearer '+s.token},body:data});const out=await r.json();if(!r.ok)throw Error(out.detail||'Confronto recusado');await manageOrderInvoices(id);$('invoiceNotice').textContent='NF-e '+out.invoiceNumber+' confrontada: '+out.status}catch(err){notice.textContent=err.message}}
async function uploadOrderFiles(orderId,files){for(const file of files){const form=new FormData();form.append('file',file);const response=await fetch(s.server+'/api/orders/'+encodeURIComponent(orderId)+'/attachments',{method:'POST',headers:{Authorization:'Bearer '+s.token},body:form});if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(data.detail||'Envio recusado')}}}
async function manageOrderAttachments(id){const panel=$('orderAttachments');if(!panel||!s.token)return alert('Entre no sistema para acessar comprovantes.');panel.innerHTML='<div class="box">Carregando comprovantes…</div>';try{const response=await fetch(s.server+'/api/orders/'+encodeURIComponent(id)+'/attachments',{headers:{Authorization:'Bearer '+s.token}});if(!response.ok)throw Error('Não foi possível consultar os comprovantes.');const files=await response.json(),order=s.orders.find(x=>x.id===id),editable=['Pendente','Cancelado'].includes(order?.status);panel.innerHTML='<div class="box"><h3>Comprovantes do pedido</h3><p class="muted">Até cinco arquivos PDF, JPG ou PNG de 5 MB. Somente usuários conectados podem acessar.</p>'+files.map(f=>'<p>'+esc(f.name)+' ('+Math.ceil(f.size/1024)+' KB) <button type="button" onclick="downloadOrderAttachment(\''+esc(id)+'\',\''+esc(f.id)+'\',\''+esc(encodeURIComponent(f.name))+'\')">Baixar</button> '+(editable?'<button type="button" class="secondary" onclick="deleteOrderAttachment(\''+esc(id)+'\',\''+esc(f.id)+'\')">Excluir</button>':'')+'</p>').join('')+'<label>Adicionar comprovantes<input id="moreOrderFiles" type="file" accept=".pdf,.jpg,.jpeg,.png" multiple></label><button type="button" onclick="addOrderAttachments(\''+esc(id)+'\')">Enviar arquivos</button></div>';panel.scrollIntoView({behavior:'smooth'})}catch(err){panel.textContent=err.message}}
async function addOrderAttachments(id){const files=[...$('moreOrderFiles').files];if(!files.length)return;if(files.length>5||files.some(f=>f.size>5*1024*1024||f.size===0||!/[.]pdf$|[.]jpe?g$|[.]png$/i.test(f.name)))return alert('Envie até cinco arquivos PDF, JPG ou PNG de no máximo 5 MB.');try{await uploadOrderFiles(id,files);await manageOrderAttachments(id)}catch(err){alert(err.message)}}
async function downloadOrderAttachment(id,attachmentId,name){try{const r=await fetch(s.server+'/api/orders/'+encodeURIComponent(id)+'/attachments/'+encodeURIComponent(attachmentId),{headers:{Authorization:'Bearer '+s.token}});if(!r.ok)throw Error('Download recusado');downloadBlob(await r.blob(),decodeURIComponent(name))}catch(err){alert(err.message)}}
async function deleteOrderAttachment(id,attachmentId){if(!confirm('Excluir este comprovante?'))return;const r=await fetch(s.server+'/api/orders/'+encodeURIComponent(id)+'/attachments/'+encodeURIComponent(attachmentId),{method:'DELETE',headers:{Authorization:'Bearer '+s.token}});if(!r.ok){const data=await r.json().catch(()=>({}));return alert(data.detail||'Exclusão recusada')}await manageOrderAttachments(id)}
function pdfText(value){return String(value??'').normalize('NFC').replace(/[–—]/g,'-').replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/[^\x20-\xFF]/g,'?').replace(/([\\()])/g,'\\$1')}
function wrapPDF(text,size=88){let words=String(text||'').split(/\s+/),lines=[],line='';for(const word of words){if((line+' '+word).trim().length>size){if(line)lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);return lines.length?lines:['']}
function orderPDFBlob(order){
 const customer=client(order.clientId),items=order.items||[];
 const documentType=order.status==='Orçamento'?'ORÇAMENTO COMERCIAL':'PEDIDO COMERCIAL';
 const bounds=[42,112,372,420,487,553],pages=[];
 const short=(value,max=96)=>{let t=String(value??'').trim();return t.length>max?t.slice(0,max-3)+'...':t};
 const date=(value)=>{let m=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:String(value||'—')};
 const escPDF=(value)=>pdfText(String(value??''));
 const textAt=(x,y,value,size=9,bold=false,color='dark')=>`${color==='white'?'1 1 1':color==='gold'?'.72 .55 .22':'.15 .13 .10'} rg BT /${bold?'F2':'F1'} ${size} Tf ${x} ${y} Td (${escPDF(value)}) Tj ET\n`;
 const measureCtx=typeof document==='undefined'?null:document.createElement('canvas').getContext('2d');
 const textWidth=(value,size,bold=false)=>{let label=String(value??'');if(!measureCtx)return label.length*size*.52;measureCtx.font=`${bold?'bold ':''}${size}px Helvetica, Arial, sans-serif`;return measureCtx.measureText(label).width};
 const fit=(value,maxWidth,size,bold=false)=>{let label=String(value??'');if(textWidth(label,size,bold)<=maxWidth)return label;while(label&&textWidth(label+'...',size,bold)>maxWidth)label=label.slice(0,-1);return label.trimEnd()+'...'};
 const rightAt=(right,y,value,size=9,bold=false)=>textAt(Math.max(42,right-textWidth(value,size,bold)),y,value,size,bold);
 const centerAt=(left,right,y,value,size=9,bold=false)=>textAt((left+right-textWidth(value,size,bold))/2,y,value,size,bold);
 const rule=(x1,y1,x2,y2,width=.5)=>`.79 .73 .62 RG ${width} w ${x1} ${y1} m ${x2} ${y2} l S\n`;
 const fill=(x,y,w,h,r=.95,g=.96,b=.96)=>`${r} ${g} ${b} rg ${x} ${y} ${w} ${h} re f 0 0 0 rg\n`;
 const head=(number)=>{
  let out=fill(42,783,511,39,.01,.27,.31)+fill(42,781,511,2,.72,.55,.22)+'q 56 0 0 37 46 784 cm /Logo Do Q\n'+textAt(113,800,documentType,9,true,'gold');
  out+=textAt(42,763,`${order.status==='Orçamento'?'ORÇAMENTO':'PEDIDO'} Nº ${orderLabel(order.orderNumber)}`,11,true)+rightAt(553,763,`Emissão: ${date(order.date)}`,8.5);
  out+=rule(42,758,553,758,1);
  if(number===1){
   out+=textAt(42,742,fit(`Marca / indústria: ${order.brand||'Não informada'}`,370,9),9);
   out+=rightAt(553,742,`Tabela: ${order.priceTable||order.state||'—'}`,9,true);
   out+=textAt(42,723,fit(`Cliente: ${customer.name||'Não informado'}`,505,9.5,true),9.5,true);
   out+=textAt(42,707,fit(`CNPJ/CPF: ${customer.taxId||'Não informado'}    IE: ${customer.stateRegistration||'Não informada'}`,505,8.5),8.5);
   out+=textAt(42,691,fit(`Endereço: ${customer.address||'Não informado'}`,505,8.5),8.5);
   out+=textAt(42,675,fit(`Bairro: ${customer.district||'—'}    Cidade/UF: ${customer.city||'—'} / ${customer.state||'—'}`,505,8.5),8.5);
   out+=textAt(42,659,fit(`Contato: ${customer.contact||customer.phone||'—'}    Vendedor: ${orderSeller(order)||'Não informado'} · Lançamento: ${order.enteredBy||order.user||'—'}${(order.enteredBy||order.user)==='Laís'?' (Adm)':''}`,505,8.5),8.5);
   out+=rule(42,647,553,647);
   out+=textAt(42,632,fit(`Condição de pagamento: ${order.paymentTerms||'Não informada'}`,380,8.5),8.5);
   out+=rightAt(553,632,`Situação: ${order.status||'—'}`,8.5);
  }else out+=textAt(42,740,`Cliente: ${short(customer.name||'Não informado',80)}`,9,true);
  if(number===1){const names=[...new Set(items.map(i=>s.priceTables.find(t=>t.id===i.tableId)?.title).filter(Boolean))].join('; ');if(names)out+=textAt(42,618,fit('Tabelas: '+names,505,7),7)}
  const top=number===1?603:722;
  out+=fill(42,top-23,511,23,.95,.92,.85);
  for(const x of bounds)out+=rule(x,top,x,top-23);
  out+=rule(42,top,553,top,1)+rule(42,top-23,553,top-23,1);
  out+=centerAt(bounds[0],bounds[1],top-16,'CÓDIGO',8,true)+centerAt(bounds[1],bounds[2],top-16,'DESCRIÇÃO',8,true);
  out+=centerAt(bounds[2],bounds[3],top-16,'QTD.',8,true)+centerAt(bounds[3],bounds[4],top-16,'UNITÁRIO',8,true)+centerAt(bounds[4],bounds[5],top-16,'VALOR',8,true);
  return {out,top};
 };
 let index=0,page=1;
 do{
  const {out:header,top}=head(page);let stream=header,y=top-23;
  const bottom=155;
  while(index<items.length&&y-25>=bottom){
   const item=items[index++],qty=Number(item.quantity||0),unit=priceCents(item.unitPrice)/100;
   const description=wrapPDF((order.brand==='Multimarcas'?String(item.brand||'')+' · ':'')+(item.description||item.sku),47);
   stream+=textAt(46,y-15,short(item.sku,14),7.8);
   stream+=textAt(116,y-12,fit(description[0],252,7.8),7.8);
   if(description.length>1)stream+=textAt(116,y-21,fit(description.slice(1).join(' '),252,7.8),7.8);
   stream+=centerAt(bounds[2],bounds[3],y-15,new Intl.NumberFormat('pt-BR').format(qty),8.5);
   stream+=centerAt(bounds[3],bounds[4],y-15,money(unit).replace(/^R\$\s*/,''),8.5);
   stream+=centerAt(bounds[4],bounds[5],y-15,money(unit*qty).replace(/^R\$\s*/,''),8.5);
   y-=25;stream+=rule(42,y,553,y);
   for(const x of bounds)stream+=rule(x,y,x,y+25);
  }
  if(index===items.length){
   stream+=fill(42,y-34,511,34,.95,.92,.85)+rule(42,y,553,y,1)+rule(42,y-34,553,y-34,1);
   stream+=textAt(48,y-22,'VALOR TOTAL DO PEDIDO',10,true)+rightAt(548,y-22,money(order.amount),11,true);
   stream+=textAt(42,y-52,'Espelho comercial para conferência. Não é DANFE nem documento fiscal.',7.5);
  }
  stream+=rule(42,55,553,55)+textAt(42,43,'L2 ONE  |  Representações comerciais PA / AP',7.5)+rightAt(553,43,`Página ${page}`,7.5);
  pages.push(stream);page++;
 }while(index<items.length);
 const objects=['','','','',''],pageIds=[],contentIds=[];
 for(let i=0;i<pages.length;i++){pageIds.push(6+i*2);contentIds.push(7+i*2)}
 objects[0]='<< /Type /Catalog /Pages 2 0 R >>';
 objects[1]=`<< /Type /Pages /Kids [${pageIds.map(id=>id+' 0 R').join(' ')}] /Count ${pages.length} >>`;
 objects[2]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
 objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
 const logoBinary=atob(L2_LOGO_JPEG_BASE64);
 objects[4]=`<< /Type /XObject /Subtype /Image /Width 1152 /Height 768 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${logoBinary.length} >>\nstream\n${logoBinary}\nendstream`;
 for(let i=0;i<pages.length;i++){
  const stream=pages[i];objects[pageIds[i]-1]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Logo 5 0 R >> >> /Contents ${contentIds[i]} 0 R >>`;
  objects[contentIds[i]-1]=`<< /Length ${stream.length} >>\nstream\n${stream}endstream`;
 }
 let pdf='%PDF-1.4\n%âãÏÓ\n',offsets=[0];
 for(let i=0;i<objects.length;i++){offsets[i+1]=pdf.length;pdf+=`${i+1} 0 obj\n${objects[i]}\nendobj\n`}
 const xref=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;
 for(let i=1;i<=objects.length;i++)pdf+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';
 pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
 return new Blob([Uint8Array.from([...pdf].map(ch=>ch.charCodeAt(0)&255))],{type:'application/pdf'});
}
function orderFileName(order){let name=(client(order.clientId).name||'cliente').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase();return `${order.status==='Orçamento'?'orcamento':'pedido'}-${orderLabel(order.orderNumber)}-${order.date}-${name||'cliente'}.pdf`}
function downloadBlob(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function downloadOrderPDF(id){let order=s.orders.find(x=>x.id===id);if(!order)return;if(!order.orderNumber)return alert('Aguarde a sincronização para gerar o PDF com número.');downloadBlob(orderPDFBlob(order),orderFileName(order))}
function orderShareText(order){let c=client(order.clientId),items=(order.items||[]).reduce((n,i)=>n+Number(i.quantity||0),0);return `${order.status==='Orçamento'?'Orçamento':'Pedido'} nº ${orderLabel(order.orderNumber)} - L2 ONE\nCliente: ${c.name||'-'}\nTabela: ${order.priceTable||order.state||'-'}\nMarca: ${order.brand||'-'}\nItens: ${items}\nTotal: ${money(order.amount)}`}
async function shareOrderPDF(id,automatic=false){let order=s.orders.find(x=>x.id===id);if(!order)return;if(!order.orderNumber)return alert('Aguarde a sincronização para gerar o PDF com número.');let blob=orderPDFBlob(order),name=orderFileName(order);downloadBlob(blob,name);let file=new File([blob],name,{type:'application/pdf'}),data={title:'Pedido L2 ONE',text:orderShareText(order),files:[file]};if(navigator.share&&navigator.canShare?.(data)){try{await navigator.share(data);return}catch(err){if(err.name==='AbortError')return}}let phone=digits(client(order.clientId).phone);if(phone.length===10||phone.length===11)phone='55'+phone;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(orderShareText(order)+'\n\nO PDF foi baixado. Anexe o arquivo '+name+' nesta conversa.')}`,'_blank','noopener');if(automatic)alert('Pedido finalizado. O PDF foi salvo e o WhatsApp foi aberto para o envio.')}
async function importPrices(e){
 e.preventDefault();
 if(!s.server||!s.token)return alert('Conecte o sistema ao servidor antes de importar preços.');
 const form=new FormData(e.target),file=form.get('priceFile');
 const source=file?.size?await file.text():String(form.get('prices')||'');
 const lines=source.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),prices=[],seen=new Set();
 if(!lines.length)return alert('Selecione um arquivo ou cole a tabela de preços.');
 for(let i=0;i<lines.length;i++){
  const parts=lines[i].split(';').map(x=>x.trim());
  if(i===0&&/marca/i.test(parts[0])&&/sku/i.test(parts[1]||''))continue;
  if(parts.length!==5)return alert(`Linha ${i+1}: use Marca; SKU; Descrição; UF; Preço.`);
  let [brand,sku,description,state,value]=parts,cents=parseBRLCents(value);
  state=state.toUpperCase();
  if(!brand||!sku||!['PA','AP','ALL'].includes(state)||!Number.isFinite(cents)||cents<=0)return alert(`Linha ${i+1}: confira marca, SKU, UF e preço.`);
  const explicit=String(form.get('tableId')||''),choices=s.priceTables.filter(t=>t.active&&t.brand===brand&&(t.state===state||t.state==='ALL')),table=explicit?s.priceTables.find(t=>t.id===explicit&&t.active):choices.length===1?choices[0]:null;if(!table||table.brand!==brand||(table.state!=='ALL'&&table.state!==state))return alert(`Linha ${i+1}: selecione a tabela comercial de destino compatível.`);state=table.state;const tableId=table.id,key=tableId+'|'+sku;
  if(seen.has(key))return alert(`Linha ${i+1}: SKU repetido para a mesma marca e UF.`);
  seen.add(key);prices.push({brand,sku,description,state,tableId,price:(cents/100).toFixed(2)});
 }
 const button=e.target.querySelector('button[type="submit"]')||e.target.querySelector('button');
 const status=$('priceImportStatus');
 if(button)button.disabled=true;
 let completed=0;
 try{
  for(let offset=0;offset<prices.length;offset+=500){
   if(status)status.textContent=`Importando ${completed} de ${prices.length} preços…`;
   const response=await fetch(s.server+'/api/prices/import',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:JSON.stringify({prices:prices.slice(offset,offset+500)})});
   const data=await response.json();
   if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Importação recusada.');
   completed+=data.imported;
  }
  if(status)status.textContent=`${completed} preços importados. Sincronizando catálogo…`;
  await sync();show('marcas');
  alert(`${completed} preço(s) importado(s) com sucesso.`);
 }catch(err){
  if(status)status.textContent=`${completed} de ${prices.length} importados. É seguro repetir o mesmo arquivo.`;
  alert('Importação interrompida: '+err.message+'. '+completed+' registros enviados; repita o mesmo arquivo para concluir.');
 }finally{if(button)button.disabled=false}
}
async function saveVisit(e){e.preventDefault();const form=e.target,files=[...(form.elements.photos?.files||[])];if(files.length>3||files.some(f=>f.size>5*1024*1024||!['image/jpeg','image/png'].includes(f.type)))return alert('Selecione até 3 fotos JPG ou PNG com até 5 MB cada.');let d=Object.fromEntries(new FormData(form));if(!d.next?.trim()||!d.returnDate)return alert('Informe a próxima ação e a data de retorno.');delete d.photos;const editing=!!d.id,previous=s.visits.find(x=>x.id===d.id);if(d.checkOut&&!d.checkIn)return alert('Registre o check-in antes do check-out.');if(d.checkIn&&d.checkOut&&d.checkOut<d.checkIn)return alert('O check-out deve ser posterior ao check-in.');d.id=d.id||uid();d.user=d.user||s.user;d={...previous,...d};s.visits=s.visits.filter(x=>x.id!==d.id);s.visits.push(d);await queue('visit',d);if(d.next){let previousTask=s.tasks.find(t=>t.sourceVisitId===d.id),t={...previousTask,id:previousTask?.id||uid(),sourceVisitId:d.id,clientId:d.clientId,text:d.next,date:d.returnDate,user:d.user,status:previousTask?.status||'Aberta'};s.tasks=s.tasks.filter(x=>x.id!==t.id);s.tasks.push(t);queue('task',t)}if(files.length){if(!s.token||!navigator.onLine||s.pending.some(x=>x.type==='visit'&&x.data.id===d.id))alert('Visita salva. Conecte-se e sincronize antes de anexar as fotos.');else try{for(const file of files){const fd=new FormData();fd.append('file',file);const r=await fetch(s.server+'/api/visits/'+encodeURIComponent(d.id)+'/photos',{method:'POST',headers:{Authorization:'Bearer '+s.token},body:fd});if(!r.ok)throw Error((await r.json()).detail||'Envio recusado')}}catch(err){alert('Visita salva, mas uma foto não foi enviada: '+err.message)}}CommercialDrafts.clear('visit:'+(editing?d.id:'new'));window.prefillId='';show('hoje')}
function visitStamp(field){const input=document.querySelector('#visitForm [name="'+field+'"]');if(input){const d=new Date();input.value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);CommercialDrafts.capture(input.form)}}
function editVisit(id){const visit=s.visits.find(x=>x.id===id);if(!visit)return;window.prefillId=visit.clientId;show('registro');const form=$('visitForm');for(const [name,value] of Object.entries(visit))if(form.elements[name]&&name!=='photos')form.elements[name].value=value??'';CommercialDrafts.bind();form.scrollIntoView({behavior:'smooth',block:'start'})}
async function manageVisitPhotos(id){const box=$('visitPhotos');if(!box)return;try{const r=await fetch(s.server+'/api/visits/'+encodeURIComponent(id)+'/photos',{headers:{Authorization:'Bearer '+s.token}});if(!r.ok)throw Error((await r.json()).detail||'Não foi possível listar as fotos');const files=await r.json();box.innerHTML='<h4>Fotos do atendimento</h4>'+files.map(f=>'<p>'+esc(f.name)+' · '+esc(f.uploadedBy)+' <button onclick="downloadVisitPhoto(\''+esc(id)+'\',\''+esc(f.id)+'\',\''+esc(encodeURIComponent(f.name))+'\')">Baixar</button></p>').join('')+'<label>Adicionar fotos<input id="visitMorePhotos" type="file" accept="image/jpeg,image/png" capture="environment" multiple></label><button onclick="addVisitPhotos(\''+esc(id)+'\')">Enviar fotos</button>'}catch(err){box.textContent=err.message}}
