 if(!o)return;
 if(!o.sellerResponsible){if(administrativeOrderEntry()){alert('Informe o vendedor responsável na lista de pedidos antes de alterar o status.');show('pedidos');return}o.sellerResponsible=s.user;o.commissionSeller=s.user}
