async function applyClientCleanup(preview){if(!confirm('Arquivar '+preview.outside+' cliente(s) fora de PA/AP e unir '+preview.duplicates+' duplicado(s) confirmado(s)?'))return;try{const r=await fetch(s.server+'/api/admin/clients/cleanup',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:JSON.stringify({previewHash:preview.previewHash})});const result=await r.json();if(!r.ok)throw Error(result.detail||'Limpeza recusada');await sync();alert('Base atualizada: '+result.remaining+' clientes PA/AP.');show('config')}catch(err){alert(err.message)}}
function repairQueuedOrderSeller(id,seller){
 // Renew IDs so an in-flight response cannot acknowledge a repaired version.
 for(const change of s.pending)if(change.type==='order'&&change.data.id===id){
  change.data={...change.data,sellerResponsible:seller,commissionSeller:seller};
  change.changeId=uid();
 }
}
function pendingOrderSellerIssues(){
 return [...new Map(s.pending.filter(x=>x.type==='order'&&(!String(x.data.sellerResponsible||'').trim()||x.data.sellerResponsible==='Laís')).map(x=>[x.data.id,x])).values()];
}
function pendingOrderRepairsHTML(){
 const issues=pendingOrderSellerIssues();if(!issues.length)return '';
 return '<div id="pendingOrderRepairs" class="box"><h3>Pedidos pendentes sem vendedor responsável</h3><p>Escolha o vendedor de cada pedido. A correção será aplicada a todas as versões pendentes do mesmo pedido.</p>'+issues.map(x=>'<form onsubmit="repairPendingOrderSeller(event,'+esc(JSON.stringify(x.data.id))+')"><label>Pedido '+esc(x.data.orderNumber||x.data.id)+' · '+esc(client(x.data.clientId).name||x.data.clientId)+' · '+esc(x.data.date||'')+'<select name="sellerResponsible" required><option value="">Selecione o vendedor</option>'+sellerOptions('')+'</select></label><button>Corrigir vendedor pendente</button></form>').join('')+'</div>';
}
function repairPendingOrderSeller(event,id){
 event.preventDefault();if(!administrativeOrderEntry())return;
 const seller=String(new FormData(event.target).get('sellerResponsible')||'');
 if(!seller||seller==='Laís'||!s.sellers.includes(seller))return alert('Selecione um vendedor ativo.');
 repairQueuedOrderSeller(id,seller);
 const order=s.orders.find(x=>x.id===id);if(order){order.sellerResponsible=seller;order.commissionSeller=seller}
 save();show('config');sync();
}
function pendingClientRegistrationIssues(){
 // Cada alteração antiga é enviada ao servidor; uma versão mais recente do
 // mesmo cliente não torna válida uma versão anterior ainda na fila.
 const issues=s.pending.filter(x=>x.type==='client').filter(x=>{
  const ie=String(x.data.stateRegistration||'').trim().toUpperCase();
  return (x.data.taxId||ie)&&ie!=='ISENTO'&&!/^\d{7,14}$/.test(ie.replace(/[.\-/\s]/g,''));
 });
 return [...new Map(issues.map(x=>[x.data.id,x])).values()];
}
function pendingClientRepairsHTML(){
 const issues=pendingClientRegistrationIssues();
 if(!issues.length)return '';
 return `<div id="pendingClientRepairs" class="box"><h3>Cadastros pendentes que precisam de correção</h3><p>Corrija a inscrição estadual e sincronize novamente. As demais alterações continuam salvas neste aparelho.</p>${issues.map(x=>`<form onsubmit="repairPendingClientRegistration(event,'${esc(x.changeId)}')"><label>${esc(x.data.name||x.data.id)} · CNPJ ${esc(x.data.taxId||'não informado')}<input name="registration" required value="${esc(x.data.stateRegistration||'')}" placeholder="7 a 14 dígitos ou ISENTO"></label><button>Corrigir cadastro pendente</button></form>`).join('')}</div>`;
}
function repairPendingClientRegistration(event,changeId){
 event.preventDefault();const change=s.pending.find(x=>x.changeId===changeId&&x.type==='client');if(!change)return;
 const value=String(new FormData(event.target).get('registration')||'').trim().toUpperCase();
 const registration=value==='ISENTO'?value:/^[\d.\-/\s]+$/.test(value)?digits(value):'';
 if(registration!=='ISENTO'&&!/^\d{7,14}$/.test(registration))return alert('Informe de 7 a 14 dígitos ou ISENTO.');
 for(const pending of s.pending)if(pending.type==='client'&&pending.data.id===change.data.id)pending.data.stateRegistration=registration;
 const customer=s.clients.find(c=>c.id===change.data.id);if(customer)customer.stateRegistration=registration;
 save();show('config');sync();
}
