function whatsappPhone(value){let phone=digits(value);if(phone.length===10||phone.length===11)phone='55'+phone;return /^55\d{10,11}$/.test(phone)?phone:''}
function renderWhatsappBase(){
 const templates=s.whatsappTemplates||[],customers=s.clients.slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'pt-BR'));
 const orders=s.orders.filter(o=>o.orderNumber).slice().reverse();
 const currentTemplate=templates.find(x=>x.id===window.whatsappTemplateId),currentClient=customers.find(x=>x.id===window.whatsappClientId);
 return `<div class="page-heading"><div><span class="eyebrow">Relacionamento com clientes</span><h2>Chat</h2><p>Organize mensagens de promoções e campanhas e envie pedidos diretamente ao contato do cliente.</p></div></div>
 ${['Ana Paula','Euler','Laís','Marlene'].includes(s.user)?'<div class="box"><h3>Atendimento de clientes</h3><p>O painel da equipe serve para responder às conversas iniciadas pelos clientes. Para enviar uma tabela a um cliente, selecione-o abaixo e use o compartilhamento do PDF.</p><a class="button" href="/atendimento/equipe" target="_blank" rel="noopener">Abrir painel de atendimento</a> <details><summary>Link público para compartilhar com clientes</summary><p>Este endereço é destinado ao cliente, que inicia uma solicitação para a equipe: <a href="/atendimento" target="_blank" rel="noopener">Link do cliente</a></p></details></div>':''}
 <div class="box"><h3>Modelos de mensagem</h3><form id="whatsappTemplateForm"><div class="row"><label>Categoria<select name="category"><option>Promoção</option><option>Campanha</option></select></label><label>Título<input name="title" required maxlength="100" placeholder="Ex.: Oferta da semana"></label></div><label>Mensagem<textarea name="message" required maxlength="3000" rows="5" placeholder="Olá, {cliente}! Confira as novidades da {marca}."></textarea></label><p class="muted">Use {cliente} e {marca} para personalizar o texto. Os modelos são compartilhados com a equipe após a sincronização.</p><button type="submit">Salvar modelo</button></form>${templates.length?`<div class="scroll"><table><tr><th>Categoria</th><th>Modelo</th><th>Ação</th></tr>${templates.map(t=>`<tr><td>${esc(t.category)}</td><td>${esc(t.title)}</td><td><button type="button" class="secondary" onclick="selectWhatsappTemplate('${esc(t.id)}')">Selecionar</button> <button type="button" class="secondary" onclick="deleteEntity('whatsapp_template','${esc(t.id)}')">Excluir</button></td></tr>`).join('')}</table></div>`:''}</div>
 <div class="box"><h3>Enviar promoção ou campanha</h3><label>Cliente<select id="whatsappClient" onchange="window.whatsappClientId=this.value;updateTableDocumentOptions()"><option value="">Selecione</option>${customers.map(c=>`<option value="${esc(c.id)}" ${c.id===currentClient?.id?'selected':''}>${esc(c.name||'Sem nome')} · ${esc(c.phone||'sem telefone')}</option>`).join('')}</select></label><label>Modelo selecionado<input id="whatsappSelectedTitle" readonly value="${esc(currentTemplate?.title||'Selecione um modelo acima')}"></label><label>Marca (opcional)<input id="whatsappBrand" placeholder="Marca desta campanha"></label><label>Imagem, PDF ou vídeo da campanha (opcional)<input id="whatsappCampaignMedia" type="file" accept="image/jpeg,image/png,application/pdf,video/mp4,.jpg,.jpeg,.png,.pdf,.mp4" onchange="previewWhatsappCampaignMedia(this)"></label><p id="whatsappCampaignPreview" role="status"></p><p><a class="button secondary" href="/atendimento/equipe" target="_blank" rel="noopener">Atendimento da equipe</a> <button type="button" onclick="openClientChatLink()">Abrir conversa do cliente</button> <button type="button" id="whatsappCampaignSend" onclick="sendWhatsappMessage()">Enviar pela API de mensagens</button></p><p id="whatsappCampaignStatus" role="status"></p><div id="whatsappCampaignManual"></div><p class="muted">O chat L2 abre pelo link. Na conversa externa, anexe o arquivo manualmente e confirme o destinatário. O link não envia mensagens nem anexos automaticamente. O envio automático de texto e anexos depende da API oficial. O envio depende da configuração e das regras da Meta para a janela de atendimento.</p><button type="button" class="secondary" onclick="openWhatsappHistory()">Registrar conversa no histórico</button></div>
 <div class="box"><h3>Imagem, PDF ou vídeo com legenda</h3><p class="muted">Selecione o cliente acima. Mídia e legenda são enviadas como uma única mensagem quando a API oficial estiver configurada.</p><form id="whatsappMediaForm" onsubmit="sendWhatsappMedia(event)"><label>Arquivo (JPG/PNG até 5 MB; PDF até 10 MB; MP4 até 16 MB)<input name="file" type="file" accept="image/jpeg,image/png,application/pdf,video/mp4,.jpg,.jpeg,.png,.pdf,.mp4" onchange="previewWhatsappMedia(this)" required></label><div id="whatsappMediaPreview" role="status"></div><label>Legenda<textarea name="caption" maxlength="1024" rows="3" placeholder="Descrição para acompanhar a mídia no mesmo balão"></textarea></label><button type="submit" disabled>Enviar mídia e legenda</button><p id="whatsappMediaStatus" role="status">Consultando disponibilidade do envio pela API…</p></form></div>
 <div class="box"><h3>Tabela por indústria em PDF</h3><p>Selecione o cliente acima e a tabela comercial da indústria.</p><label>Indústria e tabela<select id="tableDocumentTable" onchange="updateTableDocumentCaption()"><option value="">Selecione</option></select></label><label>Mensagem para o cliente<textarea id="tableDocumentCaption" maxlength="1024" rows="3"></textarea></label><p><button type="button" onclick="downloadTableDocument()">Gerar PDF da tabela</button> <button type="button" id="tableDocumentShare" onclick="shareTableDocument()">Compartilhar tabela pelo chat</button> <button type="button" id="tableDocumentSend" onclick="sendTableDocument()">Enviar tabela pela API</button></p><p id="tableDocumentStatus" role="status"></p></div>
 <div class="box"><h3>Cópia do pedido</h3><label>Pedido<select id="whatsappOrder"><option value="">Selecione</option>${orders.map(o=>`<option value="${esc(o.id)}">Nº ${orderLabel(o.orderNumber)} · ${esc(client(o.clientId).name||'Cliente')} · ${esc(money(o.amount))}</option>`).join('')}</select></label><p><button type="button" onclick="sendWhatsappOrder()">Compartilhar PDF do pedido</button></p><p class="muted">No celular, escolha o aplicativo de chat na tela de compartilhamento. Confira a conversa antes de enviar.</p></div>`;
}
