async function sendWhatsappMessage(){const c=s.clients.find(x=>x.id===$('whatsappClient').value),t=s.whatsappTemplates.find(x=>x.id===window.whatsappTemplateId);if(!c||!t)return alert('Selecione cliente e modelo de mensagem.');const phone=whatsappPhone(c.phone);if(!phone)return alert('Cadastre um telefone brasileiro válido com DDD para este cliente.');const message=t.message.replace(/\{cliente\}/gi,c.name||'cliente').replace(/\{marca\}/gi,$('whatsappBrand').value.trim()||'L2 Representações'),file=$('whatsappCampaignMedia')?.files?.[0];if(!file){await sendDirectWhatsappText(c.id,message,$('whatsappCampaignStatus'),$('whatsappCampaignSend'));return}if(!whatsappMediaLimit(file))return $('whatsappCampaignStatus').textContent='Selecione JPG/PNG até 5 MB, PDF até 10 MB ou MP4 até 16 MB.';if(message.length>1024)return $('whatsappCampaignStatus').textContent='Para enviar mídia com legenda, reduza a mensagem a 1024 caracteres.';if(!window.whatsappMediaReady||!s.token||!navigator.onLine){manualWhatsappCampaign(phone,message,file);return}const button=$('whatsappCampaignSend'),status=$('whatsappCampaignStatus');button.disabled=true;status.textContent='Enviando imagem e legenda juntas…';try{const result=await postWhatsappMedia(c.id,file,message);status.textContent='Mídia e legenda aceitas pela API em uma única mensagem. ID: '+result.messageId;$('whatsappCampaignMedia').value='';$('whatsappCampaignPreview').textContent='';$('whatsappCampaignManual').replaceChildren()}catch(error){status.textContent=error.message}finally{button.disabled=false}}
function whatsappMediaLimit(file){const limits={'image/jpeg':5*1024*1024,'image/png':5*1024*1024,'video/mp4':16*1024*1024,'application/pdf':10*1024*1024};return limits[file.type]&&file.size>0&&file.size<=limits[file.type]}
async function loadWhatsappCapabilities(){if(typeof updateTableDocumentOptions==='function')updateTableDocumentOptions();const form=$('whatsappMediaForm');if(!form)return;const button=form.querySelector('button[type=submit]'),status=$('whatsappMediaStatus');button.disabled=true;window.whatsappMediaReady=false;if(!s.token||!navigator.onLine){status.textContent='Entre no sistema e conecte-se à internet para enviar mídia com legenda.';return}try{const response=await fetch(s.server+'/api/whatsapp/capabilities',{headers:{Authorization:'Bearer '+s.token}});if(!response.ok)throw Error('indisponível');const capability=await response.json();if(!$('whatsappMediaForm'))return;window.whatsappMediaReady=capability.mediaWithCaption===true;button.disabled=!window.whatsappMediaReady;status.textContent=window.whatsappMediaReady?'Envio direto de mídia e legenda disponível.':'Envio de mídia indisponível até configurar a API oficial de mensagens. Nenhum envio pela API será feito até concluir a configuração.'}catch(_){if(!$('whatsappMediaForm'))return;window.whatsappMediaReady=false;button.disabled=true;status.textContent='Não foi possível verificar a integração. Tente novamente após sincronizar ou atualizar a página.'}}
function previewWhatsappMedia(input){const file=input.files?.[0],panel=$('whatsappMediaPreview');panel.textContent=file?(whatsappMediaLimit(file)?file.name+' · '+(file.size/1024/1024).toFixed(1)+' MB':'Arquivo inválido. Use JPG/PNG até 5 MB, PDF até 10 MB ou MP4 até 16 MB.'):''}
async function postWhatsappMedia(clientId,file,caption){const data=new FormData();data.set('client_id',clientId);data.set('caption',caption);data.set('file',file);const response=await fetch(s.server+'/api/whatsapp/media',{method:'POST',headers:{Authorization:'Bearer '+s.token},body:data}),result=await response.json();if(!response.ok)throw Error(result.detail||'Envio não confirmado');return result}
async function sendWhatsappMedia(event){event.preventDefault();const form=event.target,file=form.elements.file.files?.[0],clientId=$('whatsappClient')?.value,status=$('whatsappMediaStatus'),button=form.querySelector('button[type=submit]');if(!window.whatsappMediaReady){status.textContent='Envio de mídia indisponível até configurar a API oficial de mensagens.';return}if(!clientId){status.textContent='Selecione o cliente acima.';return}if(!file||!whatsappMediaLimit(file)){status.textContent='Selecione JPG/PNG até 5 MB, PDF até 10 MB ou MP4 até 16 MB.';return}if(!s.token||!navigator.onLine){status.textContent='Entre no sistema e conecte-se à internet para enviar.';return}button.disabled=true;status.textContent='Enviando mídia e legenda…';try{const result=await postWhatsappMedia(clientId,file,form.elements.caption.value);status.textContent='Mídia e legenda aceitas pela API. ID: '+result.messageId;form.reset();$('whatsappMediaPreview').textContent=''}catch(error){status.textContent=error.message}finally{button.disabled=!window.whatsappMediaReady}}
function sendWhatsappOrder(){let id=$('whatsappOrder').value,order=s.orders.find(x=>x.id===id);if(!order)return alert('Selecione um pedido.');if(!whatsappPhone(client(order.clientId).phone))return alert('Cadastre um telefone brasileiro válido com DDD para o cliente do pedido.');shareOrderPDF(id)}

async function exportPortable(){try{const r=await fetch(s.server+'/api/admin/export/portable',{headers:{Authorization:'Bearer '+s.token}});if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.detail||'Exportação recusada')}downloadBlob(await r.blob(),'l2-one-portabilidade-'+today()+'.zip')}catch(e){alert(e.message)}}


function bellaItemRate(item){const t=s.priceTables.find(t=>t.id===item.tableId);return (item.commissionRate??t?.commissionRate??0)/100}
function validateBellaDraft(order){const items=(order.items||[]).filter(i=>i.brand==='Bella Brazil');if(!items.length)return '';if(items.some(i=>Number(i.quantity)%6))return 'Bella Brazil: informe múltiplos de 6 unidades por cor/SKU.';const selected=[...new Set(items.map(i=>i.tableId))];if(selected.length!==1)return 'Escolha uma única tabela Bella Brazil.';const t=s.priceTables.find(t=>t.id===selected[0]);if(!t||!['VAREJO','REVENDA','ATACADO'].includes(t.channel))return 'Selecione a tabela Bella Brazil cadastrada.';if(['Confirmado','Faturado'].includes(order.status)){const subtotal=items.reduce((n,i)=>n+priceCents(i.unitPrice)*Number(i.quantity),0),deliveryState=order.clientState||(typeof client==='function'&&typeof stateCode==='function'?stateCode(client(order.clientId)):'')||order.priceTable,minimum=deliveryState==='AP'?300000:200000;if(subtotal<minimum)return 'Bella Brazil: mínimo '+money(minimum/100)+' em '+deliveryState+' com frete CIF.';if(!['28','28/35','30/45/60'].includes(String(order.paymentTerms||'').replace(/ /g,'')))return 'Bella Brazil: prazo 28, 28/35 ou 30/45/60 dias.';const bonus=Number(order.bellaBonusPercent||0),repeat=s.orders.some(o=>o.id!==order.id&&o.clientId===order.clientId&&['Confirmado','Faturado'].includes(o.status)&&orderBrands(o).includes('Bella Brazil'));if(!Number.isFinite(bonus)||bonus<0||bonus>100)return 'Bonificação inválida.';if(bonus&&(repeat?(s.user!=='Ana Paula'||!order.bellaBonusApproval?.trim()):(bonus<5||bonus>15)))return repeat?'Registre consulta e aprovação da bonificação pela administradora.':'Bonificação inicial de 5% a 15%, ou zero.';}return ''}

function catalogPrices(){return (s.prices||[]).filter(p=>(!window.catalogIndustry||p.brand===window.catalogIndustry)&&(!window.catalogUF||(p.state===window.catalogUF||p.state==='ALL'))&&(!window.catalogSelectedTable||catalogTableId(p)===window.catalogSelectedTable))}

async function saveSellerCommission(event){event.preventDefault();const form=event.target,member=form.dataset.member;try{const r=await fetch(s.server+'/api/admin/sellers/'+encodeURIComponent(member)+'/commission',{method:'PUT',headers:{Authorization:'Bearer '+s.token,'Content-Type':'application/json'},body:JSON.stringify({commissionRate:form.elements.commissionRate.value})});const data=await r.json();if(!r.ok)throw Error(data.detail||'Não foi possível salvar');await sync();await loadAdminTeam();$('adminTeamNotice').textContent='Percentual de '+member+' salvo no perfil. Pedidos já faturados preservam a comissão apurada.'}catch(err){$('adminTeamNotice').textContent=err.message}}
function sellerOrderRate(order){if(order.sellerCommissionRate!==undefined&&order.sellerCommissionRate!==null&&order.status==='Faturado')return Number(order.sellerCommissionRate);const rate=s.sellerCommissions.find(x=>x.user===orderSeller(order))?.rate;return rate===undefined||rate===null?null:Number(rate)}
function sellerCommissionPanel(month){if(!financeAllowed())return '';const orders=s.orders.filter(x=>x.date?.startsWith(month)&&x.status==='Faturado'&&orderSeller(x)),names=[...new Set([...s.sellers,...orders.map(orderSeller)])].filter(x=>x!=='Laís');return '<div class="box"><h3>Comissões dos vendedores</h3><p>Percentual individual do perfil aplicado ao valor faturado do pedido. Lançamentos administrativos usam o vendedor responsável. Percentual ausente fica pendente de cadastro. Faturamentos já apurados preservam o percentual registrado.</p><table><tr><th>Vendedor</th><th>Percentual atual</th><th>Faturado</th><th>Comissão apurada</th><th>Pendências</th></tr>'+names.map(name=>{const own=orders.filter(x=>orderSeller(x)===name),rate=s.sellerCommissions.find(x=>x.user===name)?.rate,pending=own.filter(x=>sellerOrderRate(x)===null),amount=own.reduce((n,x)=>n+Number(x.amount||0),0),due=own.filter(x=>sellerOrderRate(x)!==null).reduce((n,x)=>n+(x.sellerCommissionRate!=null&&x.sellerCommissionAmount!=null?priceCents(x.sellerCommissionAmount):Math.round(priceCents(x.amount)*sellerOrderRate(x)/100)),0);return '<tr><td>'+esc(name)+'</td><td>'+(rate===null||rate===undefined?'Não cadastrado':esc(rate)+'%')+'</td><td>'+money(amount)+'</td><td>'+money(due/100)+'</td><td>'+pending.length+' pedido(s) sem percentual</td></tr>'}).join('')+'</table></div>'}

// Indicadores derivados dos registros comerciais, sem duplicar dados financeiros.
function commercialMetrics(state,month,day,user,all){
 const scoped=x=>all||(x.owner||x.user)===user;
 const orders=state.orders.filter(x=>['Confirmado','Faturado'].includes(x.status)&&String(x.date||'').startsWith(month)&&(all||orderSeller(x)===user));
 const clients=state.clients.filter(scoped),opportunities=state.opportunities.filter(scoped);
 const won=new Set(['Ganho','Pedido confirmado','Faturado','Entregue','Pós-venda']);
 const closed=opportunities.filter(x=>(won.has(x.stage)||x.stage==='Perdido')&&String(x.wonAt||x.updatedAt||'').startsWith(month));
 const total=orders.reduce((n,x)=>n+Number(x.amount||0),0);
 const ages=new Map(clients.map(c=>{const dates=state.orders.filter(o=>o.clientId===c.id&&['Confirmado','Faturado'].includes(o.status)&&o.date<=day).map(o=>o.date);if(c.last_purchase&&c.last_purchase<=day)dates.push(c.last_purchase);const last=dates.sort().at(-1);return [c.id,last?Math.floor((Date.parse(day+'T12:00:00Z')-Date.parse(last+'T12:00:00Z'))/864e5):null]}));
 const goals=state.goals.filter(g=>g.month===month&&(all||g.user===user||g.user==='Equipe')).map(g=>{const value=orders.filter(o=>g.user==='Equipe'||orderSeller(o)===g.user).reduce((n,o)=>n+(g.brand?(orderBrandTotals(o).get(g.brand)||0)/100:Number(o.amount||0)),0);return {...g,value,pct:Number(g.amount)>0?value/Number(g.amount)*100:null}});
 const priorities=clients.map(c=>{let reasons=[],score=0;const age=ages.get(c.id),tasks=state.tasks.filter(x=>x.clientId===c.id&&x.status!=='Concluída'&&x.date&&x.date<=day&&scoped(x)),returns=opportunities.filter(x=>x.clientId===c.id&&!won.has(x.stage)&&x.stage!=='Perdido'&&x.followUp&&x.followUp<=day);if(tasks.length||returns.length){score+=1000;reasons.push('Retorno hoje ou vencido')}if(age>=60){score+=500;reasons.push(age+' dias sem compra')}else if(age>=15){score+=200;reasons.push('Em risco · '+age+' dias sem compra')}if(age===null){score+=100;reasons.push('Sem histórico de compra')}if(c.classification==='A')score+=80;return {client:c,score,reasons}}).filter(x=>x.score).sort((a,b)=>b.score-a.score||String(a.client.name).localeCompare(String(b.client.name))).slice(0,10);
 return {total,ticket:orders.length?total/orders.length:null,inactive:clients.filter(c=>ages.get(c.id)>=60).length,unknown:clients.filter(c=>ages.get(c.id)===null).length,conversion:closed.length?100*closed.filter(x=>won.has(x.stage)).length/closed.length:null,goals,priorities};
}
function startClientOrder(id){window.currentOrder=null;window.prefillId=id;show('pedidos');$('orderProductSearch')?.focus()}
