function renderCommercialDashboardBase(){
 const month=window.reportMonth||today().slice(0,7),m=commercialMetrics(s,month,today(),s.user,managementAllowed()),percent=v=>v===null?'Sem base':v.toFixed(1)+'%';
 return `<div class="page-heading"><div><h2>Crescimento da carteira</h2><p>${managementAllowed()?'Equipe':'Minha carteira'} · ${esc(month)}</p></div><button onclick="newOrder()">+ Pedido multimarca</button></div><label>Período<input type="month" value="${esc(month)}" onchange="window.reportMonth=this.value;show(tab)"></label><div class="cards"><div class="card">Pedidos confirmados + faturados<strong>${money(m.total)}</strong></div><div class="card">Ticket médio<strong>${m.ticket===null?'Sem pedidos':money(m.ticket)}</strong></div><div class="card">Clientes inativos · 60 dias<strong>${m.inactive}</strong><small>${m.unknown} sem histórico, tratados separadamente</small></div><div class="card">Conversão de negociações encerradas<strong>${percent(m.conversion)}</strong></div></div><p class="muted">Conversão = ganhos ÷ (ganhos + perdas) encerrados no mês. Orçamentos e rascunhos não entram em vendas. Dados ${s.pending.length?'locais com '+s.pending.length+' alteração(ões) pendente(s)':'sincronizados'} · última sincronização: ${esc(s.syncAt||'Ainda não realizada')}.</p><div class="box" id="leadConversionPanel" aria-live="polite">Conversão de leads: aguardando consulta dos registros…</div><div class="box"><h3>Metas por representante e indústria</h3><div class="scroll"><table><tr><th>Representante</th><th>Meta</th><th>Vendas</th><th>Atingimento</th></tr>${m.goals.map(g=>`<tr><td>${esc(g.user)} · ${esc(g.brand||'Geral')}</td><td>${money(g.amount)}</td><td>${money(g.value)}</td><td>${g.pct>=100?'✓ Meta batida · ':''}${percent(g.pct)}</td></tr>`).join('')||'<tr><td colspan="4">Cadastre as metas em Gestão.</td></tr>'}</table></div></div><div class="box"><h3>Quem priorizar hoje</h3>${m.priorities.map(x=>`<div class="priority-row"><b>${esc(x.client.name)}</b><p role="status">${esc(x.reasons.join(' · '))}</p><small>${esc(locationLabel(x.client))}</small><p><button onclick="startClientOrder('${esc(x.client.id)}')">Pedido</button> <button class="secondary" onclick="openClient360('${esc(x.client.id)}')">Retornar negociação</button> <button class="secondary" onclick="prefill('${esc(x.client.id)}')">Atender</button></p></div>`).join('')||'<p>Nenhuma prioridade identificada na carteira.</p>'}</div>`;
}
