function operationsOverviewHTML(selectedId){
 const state={...s,clients:selectedId?s.clients.filter(c=>c.id===selectedId):s.clients},m=CRMOperations.overview(state,today()),rows=m.pending;
 const filter=window.pendingAgendaFilter||(tab==='hoje'?'action':'all'),owner=window.pendingAgendaOwner||'',visible=CRMOperations.filterPending(rows,today(),filter,owner),limit=window.pendingAgendaLimit||50;
 const label={task:'Tarefa',visit:'Retorno',route:'Visita',opportunity:'Negociação',office:'Escritório',fulfillment:'Pedido / entrega'};
 const links=x=>(x.kind==='fulfillment'?`<button onclick="show('operations');editFulfillment('${esc(x.orderId)}')">Acompanhar pedido</button>`:x.clientId?`<button class="secondary" onclick="openClient360('${esc(x.clientId)}')">Abrir cliente</button>`:`<button class="secondary" onclick="show('office')">Abrir escritório</button>`)+(x.kind==='task'?` <button onclick="completeAgendaTask('${esc(x.id)}')">Concluir tarefa</button>`:x.kind==='route'||x.kind==='visit'?` <button onclick="prefill('${esc(x.clientId)}')">Registrar atendimento</button>`:'');
 const counts={action:rows.filter(x=>x.due&&x.due<=today()).length,all:rows.length,overdue:m.overdue,today:rows.filter(x=>x.due===today()).length,future:rows.filter(x=>x.due>today()).length,undated:rows.filter(x=>!x.due).length};
 const teamSummary=`<details><summary>Produtividade e pendências por responsável</summary><div class="scroll"><table><tr><th>Responsável</th><th>Abertas</th><th>Vencidas</th><th>Atendimentos registrados hoje</th></tr>${[...new Set([...rows.map(x=>x.owner||x.user||'Não definido'),'Ana Paula','Euler','Marlene'])].sort().map(name=>{const pending=rows.filter(x=>(x.owner||x.user||'Não definido')===name),attendances=(s.visits||[]).filter(v=>v.user===name&&v.date===today()&&CRMOperations.attendedVisit(v)).length;return `<tr><td>${esc(name)}</td><td>${pending.length}</td><td>${pending.filter(x=>x.due&&x.due<today()).length}</td><td>${attendances}</td></tr>`}).join('')}</table></div><p class="muted">Produtividade contabiliza atendimentos registrados hoje; pendências respeitam os acessos desta conta.</p></details>`;
 const controls=`<div class="workspace-actions" aria-label="Filtrar pendências">${[['action','Ação hoje'],['all','Todas'],['overdue','Vencidas'],['today','Hoje'],['future','Futuras'],['undated','Sem prazo válido']].map(([id,name])=>`<button class="${filter===id?'':'secondary'}" aria-pressed="${filter===id}" onclick="setAgendaFilter('${id}')">${name} · ${counts[id]}</button>`).join('')}</div><label>Responsável<select onchange="window.pendingAgendaOwner=this.value;window.pendingAgendaLimit=50;render()"><option value="">Toda a equipe disponível</option>${[...new Set(rows.map(x=>x.owner||x.user||'Não definido'))].sort().map(name=>`<option value="${esc(name)}" ${owner===name?'selected':''}>${esc(name)}</option>`).join('')}</select></label><p class="muted">${visible.length} pendência(s) neste filtro. Visitas sugeridas são compromissos de agenda; registre o atendimento para dar baixa.</p>`;
 return `<section class="box" aria-label="Pendências consolidadas"><h3>${tab==='hoje'?'Ações e pendências de hoje':'Visão 360° · Comando da operação'} · ${rows.length}</h3><p class="muted">Pendências da carteira, prazos críticos e retornos comerciais e de escritório. Atualize pelo botão Sincronizar.</p><p role="status"><strong style="color:#a32626;font-size:1.4em">${m.overdue} vencida(s)</strong> · ${rows.length?Math.round(m.overdue/rows.length*100):0}% dos prazos em atraso. Todas as pendências disponíveis à sua conta, inclusive retornos de atendimentos e escritório.</p>${controls}${teamSummary}<div class="scroll"><table><tr><th>Prazo</th><th>Cliente / origem</th><th>Próxima ação</th><th>Responsável</th><th></th></tr>${visible.slice(0,limit).map(x=>`<tr style="${x.due&&x.due<today()?'background:#fff1f0':x.due===today()?'background:#fff8df':''}"><td>${esc(x.due?x.due.split('-').reverse().join('/'):(x.date||x.returnDate||x.followUp||x.Prazo||x['Data retorno']?'Prazo a corrigir':'Sem prazo'))}${x.due&&x.due<today()?' · VENCIDA':''}</td><td>${esc(client(x.clientId).name||'Escritório')}</td><td><small>${esc(label[x.kind]||'Pendência')}</small><br>${esc(x.title)}</td><td>${esc(x.owner||x.user||'Não definido')}</td><td>${links(x)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhuma pendência aberta.</td></tr>'}</table></div>${visible.length>limit?'<button class="secondary" onclick="window.pendingAgendaLimit=(window.pendingAgendaLimit||50)+50;render()">Mostrar mais pendências</button>':''}</section><section class="box"><h3>Inteligência da carteira</h3><div class="cards"><div class="card">Sem atendimento neste mês<strong>${m.withoutService.length}</strong></div><div class="card">Recompra sugerida<strong>${m.reorders.length}</strong></div><div class="card">Potencial estimado<strong>${money(m.potential)}</strong><small>${m.unknownPotential} cliente(s) sem base</small></div></div><p class="muted">Potencial = oportunidades abertas; na ausência delas, ticket histórico para recompra prevista. Recompra usa a mediana dos intervalos entre pelo menos três datas de compra. Estimativas não são faturamento confirmado.</p><div class="scroll"><table><tr><th>Cliente</th><th>Atendimento no mês</th><th>Recompra prevista</th><th>Potencial / base</th><th></th></tr>${m.clients.filter(x=>!x.attended||x.reorderDate&&x.reorderDate<=today()).slice(0,100).map(x=>`<tr><td>${esc(x.client.name)}</td><td>${x.attended?'Atendido':'Sem atendimento'}</td><td>${esc(x.reorderDate||'Sem histórico suficiente')}</td><td>${x.potential===null?'Sem base':money(x.potential)}<br>${esc(x.basis)}</td><td><button onclick="suggestClientMessage('${esc(x.client.id)}')">Sugerir mensagem</button> <button onclick="prefill('${esc(x.client.id)}')">Atender</button></td></tr>`).join('')||'<tr><td colspan="5">Carteira sem alertas.</td></tr>'}</table></div></section>`;
}
function dailyGoalAlertHTML(){
 const rows=CRMOperations.targets(s,today(),s.user,managementAllowed()||hasSector('office'),orderBrandTotals,orderSeller);
 return `<section class="box" role="alert" aria-label="Meta diária prioritária"><h3>Meta de hoje · ${esc(today())}</h3><p class="muted">Distribuição por dias de segunda a sexta, sem ajuste de feriados. Meta por atendimento usa a agenda de hoje com indústria informada na rota ou no cadastro do cliente.</p><div class="scroll"><table><tr><th>Representante / indústria</th><th>Meta diária</th><th>Realizado hoje</th><th>Falta hoje</th><th>Meta semanal / realizado</th><th>Meta por atendimento</th></tr>${rows.map(g=>`<tr><td>${esc(g.user)} · ${esc(g.brand||'Geral')}</td><td>${money(g.daily)}</td><td>${money(g.dailySales)}</td><td>${money(Math.max(0,g.daily-g.dailySales))}${g.daily>0&&g.dailySales>=g.daily?' ✓ Atingida':''}</td><td>${money(g.weekly)} / ${money(g.weeklySales)}</td><td>${g.perAttendance===null?'Sem agenda por indústria':money(g.perAttendance)+' · '+g.planned+' atendimento(s)'}</td></tr>`).join('')||'<tr><td colspan="6">Meta ainda não cadastrada para este mês. Solicite a parametrização à gestão.</td></tr>'}</table></div></section>`;
}
function teamActivityHTML(){return '<section class="box"><h3>Atualizações da equipe</h3><p class="muted">Números e registros atualizados após cada salvamento. A página e os rascunhos permanecem em edição.</p><div id="commercialActivity" aria-live="polite">'+(commercialActivityHTML(window.L2Live?.activities()||[]))+'</div></section>'}
function commercialActivityHTML(events){
 const labels={client:'Cadastro do cliente atualizado',visit:'Atendimento registrado',interaction:'Contato registrado',task:'Tarefa atualizada',opportunity:'Oportunidade atualizada',order:'Pedido atualizado',route:'Rota atualizada',office_action:'Ação do escritório atualizada',office_commercial:'Demanda comercial atualizada',office_administrative:'Demanda administrativa atualizada',fulfillment:'Acompanhamento do pedido atualizado',price_table:'Tabela de preços atualizada',price:'Preço atualizado',whatsapp_media:'Arquivo enviado pelo WhatsApp',whatsapp_document:'Tabela enviada pelo WhatsApp'};
 const types={client:'Cadastro de cliente',visit:'Atendimento',interaction:'Contato',task:'Tarefa',opportunity:'Oportunidade',order:'Pedido',route:'Rota'};
 const rows=events.map(x=>{const label=x.action==='delete'?(types[x.kind]||'Registro')+' removido':labels[x.kind]||'Registro atualizado';return '<li class="activity-item"><div><strong>'+esc(label)+'</strong><p>'+esc(x.clientName||'Atividade interna')+'</p><small>'+esc(x.user||'Equipe L2')+' · '+esc(crmDateTime(x.at))+(x.local?' · Salvo no aparelho; aguardando nuvem':'')+'</small></div></li>'});
 if(!rows.length)return '<p class="muted">Nenhuma atividade registrada.</p>';
 return '<p class="muted">Horário de Belém · Atividades mais recentes primeiro</p><ul class="activity-list">'+rows.slice(0,10).join('')+'</ul>'+(rows.length>10?'<details class="activity-more"><summary>Ver mais '+(rows.length-10)+' atividades</summary><ul class="activity-list">'+rows.slice(10).join('')+'</ul></details>':'');
}
async function loadCommercialActivity(){const panel=$('commercialActivity'),token=s.token;if(!panel||!token)return;try{const r=await fetch(s.server+'/api/commercial/activity',{headers:{Authorization:'Bearer '+token}}),data=await r.json();if(!r.ok)throw Error('Não foi possível carregar as atividades. Toque em Sincronizar para tentar novamente.');if(panel!==$('commercialActivity')||token!==s.token)return;panel.innerHTML=commercialActivityHTML(data);window.commercialActivityCache=panel.innerHTML;window.commercialActivityOwner=s.user;window.commercialActivityEvents=data;panel.innerHTML=commercialActivityHTML(window.L2Live?.activities()||data);}catch(e){if(panel===$('commercialActivity'))panel.textContent='Não foi possível carregar as atividades. Toque em Sincronizar para tentar novamente.'}}
function renderCommercialDashboard(){return dailyGoalAlertHTML()+renderCommercialDashboardBase()+operationsOverviewHTML()+teamActivityHTML()}
function crmFactsHTML(clientId=''){
 const scope=x=>!clientId||x.clientId===clientId,month=today().slice(0,7),visits=s.visits.filter(x=>scope(x)&&String(x.date||'').startsWith(month)&&CRMOperations.attendedVisit(x)),contacts=(s.interactions||[]).filter(x=>scope(x)&&String(x.at||x.date||'').startsWith(month)),orders=s.orders.filter(x=>scope(x)&&String(x.date||'').startsWith(month)&&['Confirmado','Faturado'].includes(x.status)),billed=orders.filter(x=>x.status==='Faturado');
 return `<section class="box"><h3>Fatos registrados · ${esc(month)}</h3><div class="cards"><div class="card">Atendimentos no mês<strong>${visits.length}</strong></div><div class="card">Interações registradas<strong>${contacts.length}</strong></div><div class="card">Pedidos confirmados + faturados<strong>${orders.length}</strong><small>${money(orders.reduce((n,o)=>n+Number(o.amount||0),0))}</small></div><div class="card">Faturado no mês<strong>${money(billed.reduce((n,o)=>n+Number(o.amount||0),0))}</strong></div></div><p class="muted">Calculado dos atendimentos, contatos e pedidos. Reagendamentos, rascunhos e orçamentos ficam separados das realizações.</p></section>`;
}
function renderCRM(){return crmFactsHTML(window.crmClientId)+operationsOverviewHTML(window.crmClientId)+renderCRMBase()+teamActivityHTML()}
function suggestClientMessage(id){window.whatsappClientId=id;show('whatsapp');const c=client(id),m=CRMOperations.overview(s,today()).clients.find(x=>x.client.id===id);const text=m?.reorderDate&&m.reorderDate<=today()?`Olá ${c.contact||c.name}! Pelo histórico de compras, pode ser um bom momento para conferir a reposição. Como está seu estoque? Posso enviar as tabelas atualizadas das marcas que você trabalha?`:`Olá ${c.contact||c.name}! Gostaria de acompanhar suas necessidades e as oportunidades para sua loja${c.channel?' no canal '+c.channel:''}. Podemos conferir reposição e novidades das marcas que você trabalha?`;const target=$('whatsappMediaForm')?.elements.caption;if(target)target.value=text;const panel=$('suggestedCommercialText');if(panel)panel.value=text;}
function renderWhatsapp(){return renderWhatsappBase()+`<section class="box"><h3>Mensagem comercial sugerida</h3><p>Abra pela inteligência da carteira para personalizar pela recompra. Revise antes de enviar.</p><textarea id="suggestedCommercialText" rows="4" maxlength="1024"></textarea><button id="suggestedTextSend" onclick="sendSuggestedText()">Enviar mensagem pela API</button> <button class="secondary" onclick="copySuggestedCommercialText()">Copiar mensagem</button><p id="suggestedTextStatus" role="status"></p></section>`}
async function copySuggestedCommercialText(){try{await navigator.clipboard.writeText($('suggestedCommercialText').value);alert('Mensagem copiada. Revise e envie ao cliente.')}catch(_){alert('Selecione o texto para copiar manualmente.')}}
function renderClients(){return renderClientsBase()+(hasSector('clients_edit')?`<details class="box"><summary>Importar ou atualizar clientes por CSV</summary><p>Colunas: nome;cnpj;inscricao;uf;cidade;telefone;contato;responsavel. Atualização por CNPJ, preservando os demais campos. Confira a prévia antes de gravar.</p><input type="file" accept=".csv,text/csv" onchange="previewClientCSV(this)"><div id="clientCSVPreview"></div></details>`:'')}
async function previewClientCSV(input){const panel=$('clientCSVPreview');try{const file=input.files?.[0];if(!file||file.size>2*1024*1024)throw Error('Use CSV de até 2 MB.');const rows=csvRows(await file.text()),headers=rows.shift().map(norm),required=['nome','cnpj','inscricao','uf','cidade','responsavel'];if(required.some(h=>!headers.includes(h)))throw Error('Confira as colunas obrigatórias.');if(rows.length>1000)throw Error('Importe até 1.000 clientes por arquivo.');const seen=new Set();window.clientCSVPreview=rows.filter(r=>r.some(Boolean)).map((r,i)=>{const x=Object.fromEntries(headers.map((h,j)=>[h,String(r[j]||'').trim()])),taxId=digits(x.cnpj),previous=s.clients.find(c=>digits(c.taxId)===taxId),state=x.uf.toUpperCase(),registration=x.inscricao.toUpperCase();if(!x.nome||!x.cidade||!validCNPJ(taxId)||!['PA','AP'].includes(state)||!(registration==='ISENTO'||/^\d{7,14}$/.test(registration))||!s.sellers.includes(x.responsavel)||seen.has(taxId))throw Error('Confira nome, CNPJ, inscrição, UF, responsável ou duplicado na linha '+(i+2));seen.add(taxId);return {...previous,id:previous?.id||uid(),name:x.nome,taxId,stateRegistration:registration,state,city:x.cidade,phone:x.telefone||previous?.phone||'',contact:x.contato||previous?.contact||'',owner:x.responsavel}});panel.innerHTML='<p>'+window.clientCSVPreview.length+' cadastro(s) conferidos. '+window.clientCSVPreview.slice(0,10).map(c=>esc(c.name)+' · '+esc(c.state)).join('<br>')+'</p><button onclick="commitClientCSV()">Confirmar importação / atualização</button>';}catch(e){window.clientCSVPreview=[];panel.textContent=e.message}}
function commitClientCSV(){if(!hasSector('clients_edit'))return;const rows=window.clientCSVPreview||[];if(!rows.length)return;for(const c of rows){s.clients=s.clients.filter(x=>x.id!==c.id);s.clients.push(c);queue('client',c)}window.clientCSVPreview=[];show('clientes');alert('Cadastros salvos localmente. Sincronize para confirmar no servidor.')}
function pdfPriceImportHTML(){return (['Ana Paula','Laís','Marlene'].includes(s.user)&&hasSector('catalog'))?`<details class="box"><summary>Importar tabela de preços em PDF</summary><p>PDF com texto ou digitalizado de até 10 MB; imagens passam por OCR. Primeiro extraia, depois revise os itens e confirme a tabela de destino. Nenhuma gravação automática.</p><input type="file" accept="application/pdf,.pdf" onchange="previewPricePDF(this)"><p id="pdfPriceStatus" role="status"></p><div id="pdfPricePreview"></div></details>`:''}
async function previewPricePDF(input){const status=$('pdfPriceStatus');try{const file=input.files?.[0];if(!file||!s.token||!navigator.onLine)throw Error('Entre no sistema e conecte-se para extrair o PDF.');const fd=new FormData();fd.append('file',file);const r=await fetch(s.server+'/api/catalog/import-pdf/preview',{method:'POST',headers:{Authorization:'Bearer '+s.token},body:fd}),x=await r.json();if(!r.ok)throw Error(x.detail||'Extração recusada');status.textContent=x.warning+' '+x.unmatched.length+' linha(s) com valores não estruturados.';$('pdfPricePreview').innerHTML='<label>Tabela de destino<select id="pdfPriceTable">'+s.priceTables.filter(t=>t.active).map(t=>'<option value="'+esc(t.id)+'">'+esc(t.brand)+' · '+esc(t.title||t.state)+'</option>').join('')+'</select></label><label>Revise SKU;Descrição;Preço<textarea id="pdfPriceRows" rows="10">'+esc(x.candidates.map(p=>[p.sku,p.description,p.price.replace('.',',')].join(';')).join('\n'))+'</textarea></label>'+(x.candidates.length?'<button onclick="commitPricePDF()">Confirmar itens revisados</button>':'<p>Sem itens reconhecidos. Use uma tabela CSV ou PDF com texto selecionável.</p>');}catch(e){status.textContent=e.message}}
function commitPricePDF(){const table=s.priceTables.find(t=>t.id===$('pdfPriceTable').value);if(!table||!hasSector('catalog'))return alert('Selecione uma tabela ativa.');try{const seen=new Set(),rows=$('pdfPriceRows').value.split('\n').filter(x=>x.trim()).map((line,i)=>{const [sku,description,value,...extra]=line.split(';').map(x=>x.trim()),cents=parseBRLCents(value);if(extra.length||!sku||!description||description.length>250||!Number.isSafeInteger(cents)||cents<=0||seen.has(sku))throw Error('Confira a linha '+(i+1));seen.add(sku);return {brand:table.brand,tableId:table.id,state:table.state,sku,description,price:(cents/100).toFixed(2),id:table.id+'|'+sku}});if(!rows.length)throw Error('Revise pelo menos um item.');for(const row of rows){const previous=s.prices.find(p=>catalogPriceId(p)===row.id),merged={...previous,...row};s.prices=s.prices.filter(p=>catalogPriceId(p)!==row.id);s.prices.push(merged);queue('price',merged)}show('marcas');alert('Itens revisados salvos. Sincronize para validar no servidor.')}catch(e){alert(e.message)}}




async function sendDirectWhatsappText(clientId,message,status,button){if(!clientId||!s.token||!navigator.onLine){status.textContent='Selecione um cliente, entre no sistema e conecte-se à internet.';return}button.disabled=true;status.textContent='Enviando pela API de mensagens…';try{const r=await fetch(s.server+'/api/whatsapp/text',{method:'POST',headers:{Authorization:'Bearer '+s.token,'Content-Type':'application/json'},body:JSON.stringify({clientId,message})}),x=await r.json();if(!r.ok)throw Error(x.detail||'Envio não confirmado');status.textContent='Mensagem aceita pela API. ID: '+x.messageId+(x.historyRecorded?' · Registrada no histórico.':' · Falha no histórico; não repita o envio.')}catch(e){status.textContent=e.message}finally{button.disabled=false}}
function sendSuggestedText(){return sendDirectWhatsappText($('whatsappClient').value,$('suggestedCommercialText').value,$('suggestedTextStatus'),$('suggestedTextSend'))}

function openClientChatLink(){const c=client($('whatsappClient')?.value),phone=whatsappPhone(c.phone);if(!phone)return alert('Selecione um cliente com telefone brasileiro válido com DDD.');const status=$('whatsappCampaignStatus');if(status)status.textContent='Conversa aberta para envio manual. Nenhuma mensagem ou arquivo foi enviado pelo sistema. Confira o destinatário e anexe o PDF no aplicativo.';window.open('https://wa.me/'+phone,'_blank','noopener,noreferrer')}

async function shareTableDocument(){const status=$('tableDocumentStatus'),button=$('tableDocumentShare');button.disabled=true;try{const x=tableDocumentSelection();status.textContent='Gerando a tabela em PDF diretamente do CRM…';const r=await fetch(s.server+'/api/catalog/table.pdf?client_id='+encodeURIComponent(x.clientId)+'&table_id='+encodeURIComponent(x.tableId),{headers:{Authorization:'Bearer '+s.token}});if(!r.ok)throw Error((await r.json()).detail||'Falha ao gerar PDF');const blob=await r.blob(),name='tabela-'+x.tableId.replace(/[^a-zA-Z0-9_-]/g,'-')+'.pdf',file=new File([blob],name,{type:'application/pdf'});if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Tabela L2',text:x.caption});status.textContent='PDF encaminhado à tela de compartilhamento. A entrega ao cliente precisa ser conferida no aplicativo.'}else{downloadBlob(blob,name);status.textContent='PDF gerado no CRM e baixado. Anexe esse arquivo na conversa do cliente; nenhum envio automático foi realizado.';const phone=whatsappPhone(client(x.clientId).phone);if(phone){const link=document.createElement('a');link.href='https://wa.me/'+phone;link.target='_blank';link.rel='noopener noreferrer';link.className='button';link.textContent='Abrir conversa do cliente';status.append(document.createElement('br'),link)}}}catch(e){status.textContent=e.name==='AbortError'?'Compartilhamento cancelado. Nenhum envio confirmado.':e.message}finally{button.disabled=false}}

function selectedRouteDay(){const value=window.routeDay;return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)?value:today()}

function setAgendaFilter(value){window.pendingAgendaFilter=value;window.pendingAgendaLimit=50;render()}
function completeAgendaTask(id){if(!sectionAllowed('crm'))return;const task=s.tasks.find(x=>x.id===id);if(!task||task.status==='Concluída')return;task.status='Concluída';queue('task',task);render()}
